const item = $input.first().json;
const base = $env.WP_INTERNAL_URL || 'http://wordpress';
const user = $env.WP_APP_USER || 'admin';
const pass = ($env.WP_APP_PASSWORD || '').replace(/\s+/g, '');
const authHeader = 'Basic ' + Buffer.from(`${user}:${pass}`).toString('base64');

const wpReq = async (path, opts = {}) => {
  try {
    return await this.helpers.httpRequest({
      method: opts.method || 'GET',
      url: base + '/?rest_route=' + path,
      headers: { 'Content-Type': 'application/json', ...(opts.headers || {}) },
      body: opts.body,
      json: true,
      returnFullResponse: false,
    });
  } catch (err) {
    const status = err.httpCode || err.statusCode || 'ERR';
    const body = err.cause?.error || err.response?.body || err.message;
    throw new Error(`WP ${status} ${path}: ${JSON.stringify(body)}`);
  }
};

const slugify = (s) => String(s).toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/&/g, ' y ')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '');

const resolveIds = async (kind, names, createIfMissing) => {
  const ids = [];
  const notFound = [];
  for (const raw of names || []) {
    const name = String(raw).trim();
    if (!name) continue;
    const slug = slugify(name);
    let found = await wpReq(`/wp/v2/${kind}&slug=${encodeURIComponent(slug)}`);
    if (!Array.isArray(found) || found.length === 0) {
      found = await wpReq(`/wp/v2/${kind}&search=${encodeURIComponent(name)}`);
    }
    if (Array.isArray(found) && found.length > 0) {
      ids.push(found[0].id);
      continue;
    }
    if (createIfMissing) {
      const created = await wpReq(`/wp/v2/${kind}`, {
        method: 'POST',
        headers: { Authorization: authHeader },
        body: { name, slug },
      });
      ids.push(created.id);
    } else {
      notFound.push(name);
    }
  }
  return { ids, notFound };
};

const cats = await resolveIds('categories', item.wp_categories, false);
const tags = await resolveIds('tags', item.wp_tags, true);

return {
  ...item,
  category_ids: cats.ids,
  tag_ids: tags.ids,
  categories_not_found: cats.notFound,
  filename: (slugify(item.wp_title) || 'featured') + '.jpg',
};

const taxonomy = $('Resolve Taxonomy').first().json;
const media = $input.first().json;
const base = $env.WP_INTERNAL_URL || 'http://wordpress';
const user = $env.WP_APP_USER || 'admin';
const pass = ($env.WP_APP_PASSWORD || '').replace(/\s+/g, '');
const authHeader = 'Basic ' + Buffer.from(`${user}:${pass}`).toString('base64');

try {
  const post = await this.helpers.httpRequest({
    method: 'POST',
    url: base + '/?rest_route=/wp/v2/posts',
    headers: {
      'Content-Type': 'application/json',
      Authorization: authHeader,
    },
    body: {
      title: taxonomy.wp_title,
      content: taxonomy.wp_body_html,
      excerpt: taxonomy.wp_excerpt || '',
      status: 'publish',
      categories: taxonomy.category_ids,
      tags: taxonomy.tag_ids,
      ...(media && media.id ? { featured_media: media.id } : {}),
    },
    json: true,
    returnFullResponse: false,
  });
  return {
    id: post.id,
    link: post.link,
    slug: post.slug,
    featured_media_id: media?.id || null,
    categories_resolved: taxonomy.category_ids,
    tags_resolved: taxonomy.tag_ids,
    categories_not_found: taxonomy.categories_not_found,
  };
} catch (err) {
  const status = err.httpCode || err.statusCode || 'ERR';
  const body = err.cause?.error || err.response?.body || err.message;
  throw new Error(`WP ${status} create post: ${JSON.stringify(body)}`);
}

